const f=s=>formatFormula(esc(s));const getStorage=k=>{try{return JSON.parse(localStorage.getItem(k));}catch{return null;}};const setStorage=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v));}catch{}};
let room=null,session=null,localGame=null,selection={},activeMove=null,sort='element',pollTimer=null,botTimer=null,busy=false,toastTimer,modalView='',entranceMode='A',hint=0,lastError='';
