function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function showModal(title,html,wide=false,view=''){modalView=view;modal.classList.toggle('editor-modal',wide);$('#modal-body').innerHTML=`<div class="modal-heading"><h2>${esc(title)}</h2><button class="close" aria-label="关闭" id="close-modal">×</button></div>${html}`;if(!modal.open)modal.showModal();$('#close-modal').onclick=closeModal;}
