async function api(path,body){const response=await fetch(path,{method:body?'POST':'GET',headers:{...(body?{'Content-Type':'application/json'}:{}),...(session?{Authorization:'Bearer '+session.token}:{})},body:body?JSON.stringify(body):undefined});let data;try{data=await response.json();}catch{throw Error('服务器暂时没有响应，请稍后重试');}if(!response.ok){const e=new Error(data.error||'操作失败');e.status=response.status;throw e;}return data;}
