function practiceView(){const g=localGame;return{code:'练习',revision:g.turn,me:0,host:'practice-0',status:g.winner===null?'playing':'finished',options:{mode:g.mode,size:g.size,strategy:g.strategy},members:['你','林同学','周同学'].map((name,index)=>({id:'practice-'+index,name,index,ready:true})),custom:[],proposals:[],game:{...g,hand:g.hands[0],handCounts:g.hands.map(h=>h.length),stockCount:g.stock.length,discardCount:g.discard.length,moves:g.current===0&&g.winner===null?legalMoves(g):[]}};}
