function renderLobby(){const host=isHost(),me=room.members[room.me];root.innerHTML=`<section class="lobby"><div class="lobby-head"><div><span class="eyebrow">ROOM / 房间码</span><div class="room-code">${room.code}</div></div><button class="btn primary" id="invite">复制邀请链接</button></div>${proposalBanner()}<div class="lobby-grid"><div class="lobby-panel"><h2>已入座 <span class="muted">${room.members.length} / 6</span></h2>${room.members.map(m=>`<div class="seat-row"><div class="avatar ${m.index===room.me?'mine':''}">${esc(m.name.slice(0,1))}</div><div class="seat-name">${esc(m.name)}${m.index===room.me?' · 你':''}<small>${m.id===room.host?'房主':'玩家'}</small></div><span class="${m.ready?'ready-badge':'waiting-badge'}">${m.ready?'已准备':'未准备'}</span>${host&&m.id!==room.host?`<button class="quiet small" data-remove="${m.id}">移除</button>`:''}</div>`).join('')}<p class="quiet-note">各自准备好后，由房主发牌。手牌只对本人可见。</p></div><div class="lobby-panel"><h2>本局规则</h2>${optionFields(room.options,!host)}${host?'<button class="btn small wide" id="save-settings">保存设置</button>':'<p class="quiet-note">设置由房主调整。</p>'}<p class="quiet-note">大牌池 1,800 张；配方混合每局轮换扩展元素。有机物出牌需要在画布上完成结构。</p></div></div><div class="lobby-footer"><div><button class="quiet" id="leave">离开房间</button><button class="quiet" id="propose">补充物质</button></div>${host?`<button class="btn primary" id="start" ${room.members.length<2||room.members.some(m=>!m.ready)?'disabled':''}>${room.members.length<2?'等待朋友入座':room.members.some(m=>!m.ready)?'等待所有人准备':'开始发牌'}</button>`:`<button class="btn ${me.ready?'':'primary'}" id="ready">${me.ready?'取消准备':'我准备好了'}</button>`}</div></section>`;
 $('#invite').onclick=run(copyInvite);if($('#ready'))$('#ready').onclick=run(()=>action('ready',{ready:!me.ready}));if($('#start'))$('#start').onclick=run(()=>action('start'));$('#leave').onclick=run(()=>action('leave'));$('#propose').onclick=openProposal;$$('[data-remove]').forEach(b=>b.onclick=run(()=>action('remove',{memberId:b.dataset.remove})));if($('#save-settings'))$('#save-settings').onclick=run(()=>action('settings',{mode:$('#option-mode').value,size:+$('#option-size').value,strategy:$('#option-strategy').value}));attachProposal();
}
const ownTurn=()=>room?.game&&room.game.current===room.me&&room.game.winner===null;
function renderGame(){const g=room.game;root.innerHTML=`<div class="game-header"><div class="game-title"><span class="mode-chip">${g.mode}</span><div><h1>${title(g.mode)}</h1><span class="room-label">${localGame?'电脑练习':`房间 ${room.code}`} / ${g.size} 张</span></div></div><div class="game-controls">${!localGame?'<button class="quiet" id="invite">邀请</button>':''}<button class="quiet" id="history">记录</button><button class="quiet" id="room-options">${localGame?'退出练习':'房间'}</button></div></div>${lastError?`<p class="error-banner">${esc(lastError)} · 正在自动重连，你的选牌会保留。</p>`:''}${proposalBanner()}<section class="table"><div class="players">${room.members.map(m=>`<div class="player ${m.index===g.current&&g.winner===null?'turn':''}"><span class="avatar ${m.index===room.me?'mine':''}">${esc(m.name.slice(0,1))}</span><div><div class="player-name">${esc(m.name)}${m.index===room.me?' · 你':''}</div><div class="player-cards">${g.handCounts[m.index]} 张${m.index===g.current&&g.winner===null?' · 出牌中':''}</div></div></div>`).join('')}</div><div class="play-field">${tableContent(g)}</div><div class="table-bottom"><span>第 ${g.turn} 回合 · ${room.members.length} 人</span><span>${g.mode==='A'?'质量相同不能压牌':`摸牌堆 ${g.stockCount} · 连续摸牌 ${g.dryTurns}/${room.members.length*2}`}</span></div></section><div class="turn-ribbon" role="status"><strong>${g.winner!==null?`${esc(room.members[g.winner].name)}先出完了！`:ownTurn()?'轮到你出牌':`等待 ${esc(room.members[g.current].name)} 出牌`}</strong><span>${g.winner!==null?'可查看记录，或回到房间再开一局':g.mode==='A'?(g.table?'组成质量更大的物质，或者过牌':'自由领出，也可以出单个原子'):'使用全部桌面原子，不限出牌张数'}</span></div><div class="hand-head"><h2>你的手牌 <span>${g.hand.length} 张</span></h2><div class="hand-tools"><button class="quiet" id="hint">找个组合</button><label>排序 <select id="sort"><option value="element" ${sort==='element'?'selected':''}>原子序数</option><option value="mass" ${sort==='mass'?'selected':''}>质量由大到小</option></select></label></div></div><div class="hand" id="hand"></div><section class="composer" id="composer"></section>`;
 renderHand();renderComposer();$('#sort').onchange=e=>{sort=e.target.value;renderHand();};$('#hint').disabled=!ownTurn();$('#hint').onclick=()=>{const moves=g.moves;if(!moves.length){toast(g.mode==='A'?'没有更大的组合，可以过牌':'暂时没有可接组合，可以摸牌');return;}stage(moves[hint++%moves.length]);};$('#history').onclick=openHistory;$('#room-options').onclick=openRoomOptions;if($('#invite'))$('#invite').onclick=run(copyInvite);attachProposal();
}
function tableContent(g){if(g.winner!==null)return `<div class="center-empty"><span class="eyebrow">ROUND COMPLETE</span><h2>${g.winner===room.me?'你赢了。':esc(room.members[g.winner].name)+'获胜。'}</h2><p>第 ${g.turn-1} 回合出完手牌</p></div>`;if(g.mode==='B'){return `<div class="context-card"><p class="turn-caption">上家留下的原子 · 全部参与组成物质</p><div class="context-atoms">${Object.entries(countCards(g.context)).map(([e,n])=>`<span class="context-atom">${e}<small>× ${n}</small></span>`).join('')}</div><p class="played-meta">${g.table?`上一手：${f(g.table.formula)} · ${esc(g.table.name)}`:'开局原子，等你来接'}</p></div>`;}if(g.table)return `<div><p class="turn-caption">${esc(room.members[g.table.player].name)} 的出牌</p><div class="played"><div class="played-formula">${f(g.table.formula)}</div><div class="played-name">${esc(g.table.name)}</div><div class="played-meta">M ${massText(g.table.mass)} · ${g.table.cards.length} 张</div></div></div>`;return `<div class="center-empty"><span class="eyebrow">FREE LEAD</span><h2>${ownTurn()?'你的第一手。':esc(room.members[g.current].name)+'领出'}</h2><p>选原子、组物质。选牌区会实时给出结果。</p></div>`;}
function renderHand(){const counts=countCards(room.game.hand),keys=Object.keys(counts).sort((a,b)=>sort==='mass'?ELEMENTS[b].mass-ELEMENTS[a].mass:ELEMENTS[a].z-ELEMENTS[b].z),scroll=$('#hand').scrollLeft;$('#hand').innerHTML=keys.map(e=>{const el=ELEMENTS[e],picked=selection[e]||0;return `<div class="element-stack ${picked?'selected':''}" data-element="${e}"><button class="element-card" data-add="${e}" aria-label="选择一张${el.name}，共${counts[e]}张，已选${picked}张" ${!ownTurn()?'disabled':''} style="--card:${el.bg};--ink:${el.ink}" title="${el.color}"><span class="atomic-number">${el.z}</span><span class="quantity">×${counts[e]}</span><span class="element-symbol">${e}</span><span class="element-name">${el.name}</span><span class="element-mass">${massText(el.mass)}</span></button><div class="stack-controls"><button data-minus="${e}" aria-label="取消一张${el.name}" ${!picked||!ownTurn()?'disabled':''}>−</button><span class="${picked?'picked':''}">${picked} / ${counts[e]}</span><button data-add="${e}" aria-label="再选一张${el.name}" ${picked===counts[e]||!ownTurn()?'disabled':''}>+</button></div></div>`;}).join('');$('#hand').scrollLeft=scroll;$$('[data-add]').forEach(b=>b.onclick=()=>{const e=b.dataset.add;selection[e]=Math.min(counts[e],(selection[e]||0)+1);activeMove=null;renderHand();renderComposer();});$$('[data-minus]').forEach(b=>b.onclick=()=>{const e=b.dataset.minus;if(--selection[e]===0)delete selection[e];activeMove=null;renderHand();renderComposer();});}
function matches(){const key=keyOf(selection);return room.game.moves.filter(m=>keyOf(countCards(m.cards))===key);}
function renderComposer(){const n=atomCount(selection),exact=matches(),chosen=exact.find(m=>m.id===activeMove)||exact[0];if(chosen)activeMove=chosen.id;let suggestions=exact;if(!n)suggestions=room.game.moves.slice(0,10);else if(!exact.length)suggestions=room.game.moves.filter(m=>Object.entries(selection).every(([e,n])=>(countCards(m.cards)[e]||0)>=n)).slice(0,8);
 $('#composer').innerHTML=`<div class="composer-top"><div class="selection-text">${n?`已选 ${n} 张 · ${esc(compositionText(selection))}`:'点击牌面或 + 选牌，− 取消一张'}<small>${chosen?`${f(chosen.formula)} · ${esc(chosen.name)} · M ${massText(chosen.mass)}`:n?'尚未组成当前可出的物质，可以继续选牌或清空':ownTurn()?'下面的组合可一键选好，再由你确认出牌':'等待你的回合，手牌不会公开给其他人'}</small></div><div class="composer-actions"><button class="quiet" id="clear" ${!n?'disabled':''}>清空</button><button class="btn" id="skip" ${!ownTurn()||room.game.mode==='A'&&!room.game.table?'disabled':''}>${room.game.mode==='A'?'过牌':'摸一张'}</button><button class="btn primary" id="play" ${!ownTurn()||!chosen?'disabled':''}>${chosen?.graph?'绘制结构':'确认出牌'}</button></div></div>${suggestions.length?`<div class="match-list">${suggestions.map(m=>`<button class="match ${chosen?.id===m.id?'active':''}" data-match="${m.id}"><strong>${f(m.formula)}</strong><span>${esc(m.name)}</span><small>${m.cards.length} 张 · ${massText(m.mass)}${m.graph?' · 有机物':''}</small></button>`).join('')}</div>`:''}${n&&!suggestions.length?`<p class="quiet-note">没有找到？${localGame?'可以查阅物质库。':'可在物质库中提交新物质，由全体玩家确认后加入本房间。'}</p>`:''}`;
 $('#clear').onclick=()=>{selection={};activeMove=null;renderHand();renderComposer();};$('#skip').onclick=run(()=>action('skip'));$('#play').onclick=run(async()=>{const m=matches().find(m=>m.id===activeMove);if(!m)return;if(m.graph){showModal(`${m.name} · 自由结构画布`,`<div id="structure-editor"></div>`,true,'editor');mountEditor($('#structure-editor'),m,async structure=>{await action('play',{moveId:m.id,cards:m.cards,structure});closeModal();toast('结构正确，已出牌');});}else await action('play',{moveId:m.id,cards:m.cards});});$$('[data-match]').forEach(b=>b.onclick=()=>{const m=room.game.moves.find(m=>m.id===b.dataset.match);if(m)stage(m);});
}
function stage(m){selection=countCards(m.cards);activeMove=m.id;renderHand();renderComposer();}
function openHistory(){showModal('牌局记录',`<div class="library-list">${room.game.history.map(h=>`<div class="history-row">${h.type==='play'?`${esc(room.members[h.player]?.name)} 打出 ${f(h.formula)} · ${esc(h.name)}`:h.type==='reset'?'连续两圈无人出牌，更换桌面原子':h.type==='lead'?`${esc(room.members[h.player]?.name)}重新领出`:h.type==='draw'?`${esc(room.members[h.player]?.name)}摸一张`:`${esc(room.members[h.player]?.name)}过牌`}<small>第 ${h.turn} 回合${h.mass?' · M '+massText(h.mass):''}</small></div>`).join('')||'<p class="muted">还没有出牌记录。</p>'}</div>`);}
function openRoomOptions(){if(localGame){showModal('结束练习？','<p class="muted">回到首页，创建房间邀请朋友。</p><div class="modal-footer"><button class="btn primary" id="exit-practice">回到首页</button></div>');$('#exit-practice').onclick=run(async()=>{closeModal();await action('lobby');});return;}showModal('房间 '+room.code,`<p class="muted">${room.members.map(m=>esc(m.name)).join(' · ')}</p><p class="quiet-note">短暂离开后，用同一浏览器打开邀请链接可以回到座位。牌局会等待当前玩家，不会自动替你出牌。</p><div class="modal-footer"><button class="btn" id="room-propose">补充物质</button><button class="btn" id="room-invite">复制邀请</button>${isHost()?'<button class="btn primary" id="return-lobby">结束本局，返回房间</button>':''}</div>`);$('#room-invite').onclick=run(copyInvite);$('#room-propose').onclick=openProposal;if($('#return-lobby'))$('#return-lobby').onclick=()=>showModal('结束当前对局？','<p class="muted">所有人将回到等候室，当前手牌不再保留。重新准备后可以开下一局。</p><div class="modal-footer"><button class="btn danger" id="confirm-end">确认结束</button></div>');setTimeout(()=>{if($('#return-lobby'))$('#return-lobby').onclick=()=>{showModal('结束当前对局？','<p class="muted">所有人将回到等候室，当前手牌不再保留。</p><div class="modal-footer"><button class="btn danger" id="confirm-end">确认结束</button></div>');$('#confirm-end').onclick=run(async()=>{await action('lobby');closeModal();});};},0);}
function openLibrary(initial=''){showModal('物质库',`<input class="search" id="search" placeholder="名称、规范化学式或原子组成，例如 KSCN" value="${esc(initial)}" aria-label="搜索物质"><p class="quiet-note" id="library-count"></p><div class="library-list" id="library-list"></div>${room&&!localGame?'<div class="modal-footer"><button class="btn" id="custom-list">房间提案</button><button class="btn primary" id="new-substance">提交未收录物质</button></div>':''}`);const update=()=>{const q=$('#search').value.trim();let key;try{key=keyOf(parseFormula(q));}catch{}const list=allSubstances().filter(s=>!q||s.name.includes(q)||s.formula.toLowerCase().includes(q.toLowerCase())||s.key===key||s.category.includes(q));$('#library-count').textContent=`收录 ${allSubstances().length} 种 · 找到 ${list.length} 种`;$('#library-list').innerHTML=list.map(s=>`<button class="library-row" data-detail="${s.id}"><div><strong>${f(s.formula)}</strong><span>${esc(s.name)}</span></div><small>${esc(s.category)}<br>M ${massText(s.mass)}</small></button>`).join('')||'<p class="quiet-note">暂未收录。联机房间中可提交资料，由全体玩家确认后加入。</p>';$$('[data-detail]').forEach(b=>b.onclick=()=>openDetail(b.dataset.detail));};$('#search').oninput=update;if($('#new-substance'))$('#new-substance').onclick=openProposal;if($('#custom-list'))$('#custom-list').onclick=openVotes;update();}
function openDetail(id){const s=allSubstances().find(s=>s.id===id);showModal(s.name,`<div class="detail-formula">${f(s.formula)}</div><p class="muted">M ${massText(s.mass)} · ${s.size} 个原子 · ${esc(s.category)}</p><p style="margin:16px 0">${Object.entries(s.counts).map(([e,n])=>`<span class="tag">${e} × ${n}</span>`).join('')}</p>${s.graph?referenceSvg(s.graph)+`<p class="muted">${esc(s.graph.reference)}</p>`:'<p class="quiet-note">化学式采用物质的常用写法，不按原子序数或字母重新排列。</p>'}${s.source?`<p class="quiet-note">房间玩家共同确认 · <a href="${esc(s.source)}" target="_blank" rel="noopener noreferrer">查看提交资料</a></p>`:''}<div class="modal-footer"><button class="btn" id="back-library">返回物质库</button>${ownTurn()&&room.game.moves.some(m=>m.id===id)?'<button class="btn primary" id="stage-detail">选出这些牌</button>':''}</div>`);$('#back-library').onclick=()=>openLibrary();if($('#stage-detail'))$('#stage-detail').onclick=()=>{closeModal();stage(room.game.moves.find(m=>m.id===id));};}
function openProposal(){if(!room||localGame)return;showModal('把遗漏的物质补进来',`<p class="muted">提交名称、常用化学式和可核对的资料。全体玩家同意后，本房间立即允许使用。</p><p class="quiet-note">这是房间共同约定，不是自动科学认证；请核实物质真实存在。自定物质按配方出牌，不强制结构校验。</p><form id="proposal-form"><label class="field">名称<input id="proposal-name" maxlength="16" required placeholder="例如：硫氰酸钾"></label><label class="field">常用化学式<input id="proposal-formula" maxlength="80" required placeholder="例如：KSCN"></label><label class="field">参考资料链接<input id="proposal-source" type="url" required placeholder="https://…"></label><p class="form-error" id="proposal-error"></p><div class="modal-footer"><button class="btn primary" type="submit">提交给全体玩家</button></div></form>`);$('#proposal-form').onsubmit=async e=>{e.preventDefault();try{await action('propose',{name:$('#proposal-name').value,formula:$('#proposal-formula').value,source:$('#proposal-source').value});openVotes();}catch(err){$('#proposal-error').textContent=err.message;}};}
function openVotes(){showModal('房间物质提案',room.proposals.length?room.proposals.map(p=>`<article class="vote-card"><h3>${esc(p.name)} · ${f(p.formula)}</h3><p>${esc(compositionText(p.counts))} · M ${massText(p.mass)}</p><a href="${esc(p.source)}" target="_blank" rel="noopener noreferrer">核对参考资料 ↗</a><p>${p.status==='pending'?`${Object.values(p.votes).filter(Boolean).length}/${room.members.length} 人同意`:p.status==='accepted'?'已加入本房间':'未通过'}</p>${p.status==='pending'?`<div class="vote-buttons"><button class="btn primary small" data-vote="${p.id}" data-accept="true">同意收录</button><button class="btn small" data-vote="${p.id}" data-accept="false">不同意</button></div>`:''}</article>`).join(''):'<p class="muted">还没有提案。可在物质库中提交。</p>',false,'votes');$$('[data-vote]').forEach(b=>b.onclick=run(()=>action('vote',{proposalId:b.dataset.vote,accept:b.dataset.accept==='true'})));}
function openRules(){showModal('玩法与约定',`<div class="rule-block"><h3>A · 质量竞技</h3><p>牌全部分给玩家。出一个原子，或组成一种单质、无机物、有机物。跟牌的质量值必须严格更大；其余玩家都过牌后，最后出牌者自由领出。先出完获胜。</p><h3>B · 化学接龙</h3><p>每人起手 9 张。你出的 P 与桌面全部原子 C 恰好组成一种物质。旧 C 弃掉，新 P 留给下家；也可以摸一张并结束回合。不限出牌张数。连续两圈无人出牌后更换 C。先出完获胜。</p><h3>物质与化学式</h3><p>内置 ${SUBSTANCES.length} 种物质，包括 KSCN、硫代硫酸盐、配合物及常见有机物。无机物保留常用化学式；未成物质的原子组使用“元素 × 数量”显示。新物质可经房间全体玩家确认加入，标记为房间约定。</p><h3>有机物结构</h3><p>画布中的每一个圆点都是单个原子。拖动安排位置，选择单、双、三键，再点两个原子连接。可以撤销、重做和自动补氢。校验连接关系，不要求固定画法，也不区分立体异构。</p><h3>公平对局</h3><p>联网对局由服务器校验手牌、回合、质量与结构。其他人的手牌不会发到你的设备。房主调整规则后，所有人需要重新准备。短暂断线不会替玩家自动出牌。</p><h3>颜色与数值</h3><p>牌面参考单质颜色，无色气体用浅色卡面；结构画布使用常见的原子辨识色。质量按卡面固定值求和；同分异构体质量相同。这里拼的是组成和结构，不模拟真实化学反应条件。</p></div>`);}
$('#library-btn').onclick=()=>openLibrary();$('#rules-btn').onclick=openRules;
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!modal.open&&room?.game){selection={};activeMove=null;renderHand();renderComposer();}});
async function init(){const code=new URLSearchParams(location.search).get('room')||getStorage('chemcards-last-room');const token=(getStorage('chemcards-room-keys')||{})[code];if(code&&token){session={code,token};root.innerHTML='<p class="muted">正在回到房间…</p>';try{acceptRoom(await api('/api/rooms/'+code));sync();return;}catch(e){session=null;renderEntrance(e.message);return;}}renderEntrance();}
init();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_chemical_room',description:'Read current room and the current player hand; never exposes opponents hands.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(){return room?{code:room.code,status:room.status,me:room.me,members:room.members,hand:room.game?.hand,context:room.game?.context,current:room.game?.current}: {status:'home'};}})).catch(()=>{});}catch{}}
